d performance optimizations","tree":{"sha":"c3d0c9ff44d5b90e577a1c7b209088c7e986e917","url":"https://api.github.com/repos/erolkuluslu/next-auth/git/trees/c3d0c9ff44d5b90e577a1c7b209088c7e986e917"},"url":"https://api.github.com/repos/erolkuluslu/next-auth/git/commits/40b9ec945f74a9322fd2140689fa39b2bc5346ae","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/92374052?v=4","events_url":"https://api.github.com/users/erolkuluslu/events{/privacy}","followers_url":"https://api.github.com/users/erolkuluslu/followers","following_url":"https://api.github.com/users/erolkuluslu/following{/other_user}","gists_url":"https://api.github.com/users/erolkuluslu/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/erolkuluslu","id":92374052,"login":"erolkuluslu","node_id":"U_kgDOBYGEJA","organizations_url":"https://api.github.com/users/erolkuluslu/orgs","received_events_url":"https://api.github.com/users/erolkuluslu/received_events","repos_url":"https://api.github.com/users/erolkuluslu/repos","site_admin":false,"starred_url":"https://api.github.com/users/erolkuluslu/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/erolkuluslu/subscriptions","type":"User","url":"https://api.github.com/users/erolkuluslu","user_view_type":"public"},"html_url":"https://github.com/erolkuluslu/next-auth/commit/40b9ec945f74a9322fd2140689fa39b2bc5346ae","node_id":"C_kwDOPggHStoAKDQwYjllYzk0NWY3NGE5MzIyZmQyMTQwNjg5ZmEzOWIyYmM1MzQ2YWU","parents":[{"html_url":"https://github.com/erolkuluslu/next-auth/commit/e74b0d05a47096fdbcde62a315ff758028ea0102","sha":"e74b0d05a47096fdbcde62a315ff758028ea0102","url":"https://api.github.com/repos/erolkuluslu/next-auth/commits/e74b0d05a47096fdbcde62a315ff758028ea0102"}],"sha":"40b9ec945f74a9322fd2140689fa39b2bc5346ae","url":"https://api.github.com/repos/erolkuluslu/next-auth/commits/40b9ec945f74a9322fd2140689fa39b2bc5346a